FROM LA_RESOURCES T
WHERE T.DEV = 0

    AND T.id IN (
    SELECT DISTINCT T2.RESOURCEID FROM LA_ROLE_RESOURCES T2 WHERE T2.AUTHORITY IN
    #{item}
    )


    AND T.id IN
    #{item}

ORDER BY T.res_rank, T.orderNo

