UPDATE LA_RESOURCES T SET
T.res_name = #{resName},
T.orderNo = #{orderNo}, T.parentId = #{parentId, jdbcType=VARCHAR}, T.res_path = #{resPath,jdbcType=VARCHAR}, T.method = #{method,jdbcType=VARCHAR}, T.ico = #{ico,jdbcType=VARCHAR}, T.res_type = #{resType,jdbcType=INTEGER}, T.res_rank = #{resRank,jdbcType=INTEGER}, T.hidden = #{hidden,jdbcType=INTEGER}, T.parentKeys = #{parentKeys, jdbcType=VARCHAR}, T.res_mode = #{resMode,jdbcType=INTEGER}, T.remark = #{remark, jdbcType=VARCHAR}, T.key_name = #{keyName,jdbcType=VARCHAR}, T.keep_alive = #{keepAlive,jdbcType=INTEGER}, T.expand = #{expand,jdbcType=VARCHAR}, T.business_expand = #{businessExpand,jdbcType=VARCHAR}, T.res_url = #{resUrl,jdbcType=VARCHAR} WHERE T.id = #{id}

UPDATE LA_RESOURCES SET orderNo = CASE

    WHEN id = #{item.id} THEN #{item.orderNo}

END
WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES SET hidden = #{status}
WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES T SET T.res_rank = CASE

