END
WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES SET parentKeys = CASE

    WHEN id = #{item.id} THEN #{item.parentKeys, jdbcType=VARCHAR}

END WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES T SET
    T.orderNo = #{orderNo},
    T.parentId = #{parentId, jdbcType=VARCHAR},
    T.res_rank = #{resRank,jdbcType=INTEGER},
    T.parentKeys = #{parentKeys, jdbcType=VARCHAR}
WHERE T.id = #{id}

mapper.select:
SELECT PERMISSIONID
FROM LA_API_RESOURCES
WHERE RESOURCEID = #{resourceId}

SELECT DISTINCT MAR.PERMISSIONID AS permissionId, TMP.USERID AS username FROM LA_API_RESOURCES MAR LEFT JOIN ( SELECT USERID, RESOURCEID FROM LA_USER_ROLES MUR JOIN LA_ROLE_RESOURCES MRR ON MUR.AUTHORITY = MRR.AUTHORITY WHERE USERID = #{username}
AND MUR.TENANT_ID = #{tenantId}
UNION
SELECT coalesce(#{username},"USERID") USERID, RESOURCEID FROM LA_ROLE_RESOURCES WHERE AUTHORITY = CONCAT('ROLE_TENANT@', #{tenantId}) UNION
SELECT AUTHORITY USERID, RESOURCEID FROM LA_ROLE_RESOURCES MRR WHERE AUTHORITY = #{username}
AND MRR.TENANT_ID = #{tenantId}
UNION SELECT CLIENTID USERID, RESOURCEID FROM la_client_resources WHERE CLIENTID = #{username} ) TMP ON MAR.RESOURCEID = TMP.RESOURCEID WHERE TMP.USERID IS NOT NULL
